(function(){
  var P = AutoJS.players()[0];
  var Econ = Java.loadClass('com.merlinkitsune.starengine.economy.StarEngineEconomy');
  var SCC = Java.loadClass('com.merlinkitsune.astral_dice.economy.StarCoinCurrency');
  var MI = Java.loadClass('com.merlinkitsune.astral_dice.item.ModItems');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  var original = Econ.getBalance(P);
  AutoJS.write('astral_test_wallet.txt', String(original));
  Econ.setBalance(P, 7);
  var out = {};
  out.storageAvailable = Econ.isAvailable();
  out.walletEnabled = SCC.isWalletEnabled();
  out.coinValue = SCC.STAR_COIN_VALUE;
  out.bagValue = SCC.STAR_COIN_BAG_VALUE;
  out.balanceAfterSet = Econ.getBalance(P);
  out.carriedBefore = SCC.countCarriedValue(P);
  AutoJS.give('astral_dice:star_coin', 3);
  out.carriedWithCoins = SCC.countCarriedValue(P);
  out.deposited = SCC.depositAllFromInventory(P);
  out.balanceAfterDeposit = Econ.getBalance(P);
  out.carriedAfterDeposit = SCC.countCarriedValue(P);
  var coin = MI.STAR_COIN.get();
  out.withdrawTaken = SCC.withdraw(P, coin, 4);
  out.balanceAfterWithdraw = Econ.getBalance(P);
  out.carriedAfterWithdraw = SCC.countCarriedValue(P);
  out.withdrawAllTaken = SCC.withdraw(P, coin, 99);
  out.balanceAfterWithdrawAll = Econ.getBalance(P);
  out.carriedAfterWithdrawAll = SCC.countCarriedValue(P);
  out.withdrawRefused = SCC.withdraw(P, coin, 99);
  out.balanceAfterRefusal = Econ.getBalance(P);
  out.carriedAfterRefusal = SCC.countCarriedValue(P);
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var Econ = Java.loadClass('com.merlinkitsune.starengine.economy.StarEngineEconomy');
  var SCC = Java.loadClass('com.merlinkitsune.astral_dice.economy.StarCoinCurrency');
  var want = Number(AutoJS.read('astral_test_wallet.txt'));
  Econ.setBalance(P, want);
  var out = {};
  out.balanceRestoredMatches = (Econ.getBalance(P) === want);
  out.carriedFinal = SCC.countCarriedValue(P);
  AutoJS.command('clear @a');
  out.carriedAfterClear = SCC.countCarriedValue(P);
  return out;
})()
